t":"uuid"},"brandId":{"type":"string","format":"uuid"},"offerId":{"type":"string","format":"uuid"},"salesFunnelId":{"type":"string"},"stated":{"type":"boolean"},"funded":{"type":"boolean","description":"May the funnel's campaign spend at all: true when a max budget AND/OR a max volume is stated, each above 0 (owner rule 2026-10-11). A volume-only funnel is funded: it spends from the org's balance until its max volume is reached. Nothing stated = false. Read it, never re-derive it."},"fundedBy":{"type":"string","nullable":true,"enum":["max_budget","max_volume","both",null],"description":"Which stated cap funds the funnel; null when not funded."},"updatedAt":{"type":"string","nullable":true},"maxBudget":{"type":"object","nullable":true,"properties":{"amountCents":{"type":"string"},"period":{"type":"string","enum":["one_off","daily","weekly","monthly"],"description":"UTC. daily = the calendar day; weekly = Monday 00:00 to the next Monday; monthly = the calendar month; one_off = once, counted from when the cap was first stated in this period (never resets)."},"dailyBudgetCents":{"type":"string"},"periodStart":{"type":"string"},"periodEnd":{"type":"string","nullable":true},"consumedCents":{"type":"string","nullable":true},"remainingCents":{"type":"string","nullable":true},"reached":{"type":"boolean","nullable":true},"refusedSpend":{"type":"object","nullable":true,"properties":{"at":{"type":"string"},"requiredCents":{"type":"string"}},"required":["at","requiredCents"],"description":"The spend POST /v1/customer_balance/authorize refused in this window because it would have taken the cap past amountCents (reason sales_funnel_max_budget_reached). While set, reached is true: the next run's spends would be refused too. Freed by a new period or a changed amount."},"consumedUnavailableReason":{"type":"string","nullable":true,"enum":["sales_funnel_not_found","sales_funnel_catalogue_unavailable","campaign_service_unconfigured","campaign_service_unavailable","runs_service_unavailable","no_proactive_pipe","volume_not_measured_on_channel","sourcing_catalogue_unavailable","sales_funnel_campaign_not_found",null]},"consumedUnavailableDetail":{"type":"string","nullable":true}},"required":["amountCents","period","dailyBudgetCents","periodStart","periodEnd","consumedCents","remainingCents","reached","refusedSpend","consumedUnavailableReason","consumedUnavailableDetail"],"description":"consumedCents = committed NET spend (actual + provisioned, what the org pays) of every campaign on the funnel's pipes for this brand x offer PLUS every lead SOURCE campaign (Start -> Lead found) feeding those pipes (sources[]): ALL-INCLUSIVE, sourcing + sending + LLM. Runs started in [periodStart, periodEnd). reached = consumedCents >= amountCents. null + a reason when it cannot be measured, never 0."},"maxVolume":{"type":"object","nullable":true,"properties":{"count":{"type":"integer"},"period":{"type":"string","enum":["one_off","daily","weekly","monthly"],"description":"UTC. daily = the calendar day; weekly = Monday 00:00 to the next Monday; monthly = the calendar month; one_off = once, counted from when the cap was first stated in this period (never resets)."},"unit":{"type":"string","nullable":true,"enum":["first_contacts","prospects_handled","outcomes_produced",null],"description":"What a max volume counts. first_contacts: the funnel has a proactive pipe (each first contact it makes). prospects_handled: every pipe is reactive (each prospect a reactive pipe takes on once they reached its start step). outcomes_produced: every proactive pipe starts at Start and makes its own item (a Threads post, a daily video): each outcome of its leg's step declared on its campaigns' runs."},"periodStart":{"type":"string"},"periodEnd":{"type":"string","nullable":true},"consumed":{"type":"integer","nullable":true},"remaining":{"type":"integer","nullable":true},"reached":{"type":"boolean","nullable":true},"consumedUnavailableReason":{"type":"string","nullable":true,"enum":["sales_funn